try {
    const data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
    if (!data || typeof data !== "object") throw new Error("El mensaje GPS no es un objeto JSON");
    const latitude = Number(data.latitude);
    const longitude = Number(data.longitude);
    if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) throw new Error("Latitud GPS inválida");
    if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) throw new Error("Longitud GPS inválida");
    const fields = [`latitude=${latitude}`, `longitude=${longitude}`];
    for (const [key, fieldName] of [["altitude", "altitude_m"], ["satellites", "satellites"], ["hdop", "hdop"]]) {
        if (data[key] === null || data[key] === undefined || data[key] === "") continue;
        const value = Number(data[key]);
        if (!Number.isFinite(value)) throw new Error(`Campo ${key} inválido`);
        fields.push(`${fieldName}=${value}${key === "satellites" ? "i" : ""}`);
    }
    const rawCapturedAtMs = data.captured_at_ms;
    const capturedAtMs = rawCapturedAtMs === undefined || rawCapturedAtMs === null || rawCapturedAtMs === "" || Number(rawCapturedAtMs) === 0
        ? Date.now()
        : Number(rawCapturedAtMs);
    if (!Number.isSafeInteger(capturedAtMs) || capturedAtMs <= 0) throw new Error("captured_at_ms inválido");
    const timestampNs = BigInt(capturedAtMs) * 1000000n;
    msg.payload = `gps_telemetry,device=esp32-gps ${fields.join(",")} ${timestampNs}`;
    const org = encodeURIComponent(env.get("INFLUXDB_ORG") || "proyecto");
    const bucket = encodeURIComponent(env.get("INFLUXDB_BUCKET") || "gps");
    const token = env.get("INFLUXDB_TOKEN");
    if (!token) throw new Error("Falta la configuración de INFLUXDB_TOKEN");
    msg.url = `http://influxdb:8086/api/v2/write?org=${org}&bucket=${bucket}&precision=ns`;
    msg.method = "POST";
    msg.headers = { Authorization: `Token ${token}`, "Content-Type": "text/plain; charset=utf-8" };
    return msg;
} catch (error) {
    node.error(`No se pudo preparar telemetría GPS para InfluxDB: ${error.message}`, msg);
    return null;
}

if (msg.statusCode !== 204) {
    node.error(`InfluxDB rechazó la telemetría (HTTP ${msg.statusCode})`, msg);
}
return null;

msg.headers = { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" };
msg.payload = global.get("gpsRoutesHtml");
return msg;

const repo = global.get("gpsRepository");
return repo.listRoutes(msg.req.query || {}).then((routes) => {
    msg.headers = { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" };
    msg.payload = routes;
    return msg;
}).catch((error) => {
    node.error(error, msg);
    msg.statusCode = error.statusCode || 500;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: error.statusCode ? error.message : "No se pudieron consultar las rutas" };
    return msg;
});

const repo = global.get("gpsRepository");
return repo.getRoute(msg.req.params.id).then((data) => {
    msg.headers = { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" };
    if (!data) {
        msg.statusCode = 404;
        msg.payload = { error: "Ruta no encontrada" };
    } else {
        msg.payload = data;
    }
    return msg;
}).catch((error) => {
    node.error(error, msg);
    msg.statusCode = error.statusCode || 500;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: error.statusCode ? error.message : "No se pudo consultar la ruta" };
    return msg;
});

const repo = global.get("gpsRepository");
const body = msg.payload || {};
return repo.setRouteValidity(msg.req.params.id, body.is_valid, body.reason).then((data) => {
    msg.headers = { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" };
    msg.payload = { route: data.route };
    return msg;
}).catch((error) => {
    node.error(error, msg);
    msg.statusCode = error.statusCode || 500;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: error.statusCode ? error.message : "No se pudo actualizar la ruta" };
    return msg;
});

const repo = global.get("gpsRepository");
return repo.deleteRoute(msg.req.params.id).then(() => {
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { deleted: true };
    return msg;
}).catch((error) => {
    node.error(error, msg);
    msg.statusCode = error.statusCode || 500;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: error.statusCode ? error.message : "No se pudo eliminar la ruta" };
    return msg;
});

const repo = global.get("gpsRepository");
return repo.exportCsv(msg.req.params.id).then((csv) => {
    if (csv === null) {
        msg.statusCode = 404;
        msg.headers = { "Content-Type": "application/json; charset=utf-8" };
        msg.payload = { error: "Ruta no encontrada" };
    } else {
        msg.headers = { "Content-Type": "text/csv; charset=utf-8", "Content-Disposition": `attachment; filename="ruta-${Number(msg.req.params.id)}.csv"` };
        msg.payload = `\uFEFF${csv}`;
    }
    return msg;
}).catch((error) => {
    node.error(error, msg);
    msg.statusCode = error.statusCode || 500;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: error.statusCode ? error.message : "No se pudo exportar la ruta" };
    return msg;
});

const repo = global.get("gpsRepository");
return repo.exportGpx(msg.req.params.id).then((gpx) => {
    if (gpx === null) {
        msg.statusCode = 404;
        msg.headers = { "Content-Type": "application/json; charset=utf-8" };
        msg.payload = { error: "Ruta no encontrada" };
    } else {
        msg.headers = { "Content-Type": "application/gpx+xml; charset=utf-8", "Content-Disposition": `attachment; filename="ruta-${Number(msg.req.params.id)}.gpx"` };
        msg.payload = gpx;
    }
    return msg;
}).catch((error) => {
    node.error(error, msg);
    msg.statusCode = error.statusCode || 500;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: error.statusCode ? error.message : "No se pudo exportar la ruta" };
    return msg;
});
